import { createServer } from "node:http";
import { once } from "node:events";
function handleTask(req, res) {
  res.setHeader("Content-Type", "application/json");
  if (req.method === "GET" && req.url === "/tasks/1") {
    res.writeHead(200);
    res.end(JSON.stringify({ id: 1, title: "Lire" }));
    return;
  }
  res.writeHead(404);
  res.end(JSON.stringify({ error: "Absente" }));
}

test("GET /tasks/1 renvoie la tâche connue", async t => {
  const server = createServer(handleTask);
  t.after(() => new Promise(resolve => server.close(resolve)));
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const url = "http://127.0.0.1:" + server.address().port;
  const response = await fetch(url + "/tasks/1");
  assert.strictEqual(response.status, 200);
  assert.deepStrictEqual(await response.json(), {
    id: 1, title: "Lire"
  });
});

