import express from "express";
const app = express();
app.use(express.json());
app.use((req, res, next) => {
  console.log(req.method, req.path);
  next();
});
const tasks = [{ id: 1, title: "Lire" }];
const repo = { find: id => tasks.find(task => task.id === id) };
const service = id => repo.find(id);

app.get("/tasks/:id", (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id < 1) {
    return res.status(400).json({ error: "Id invalide" });
  }
  const task = service(id);
  if (!task) return res.status(404).json({ error: "Absente" });
  res.status(200).json(task);
});

app.use((err, req, res, next) => {
  if (res.headersSent) return next(err);
  let status = err.status || err.statusCode;
  if (!Number.isInteger(status) || status < 400 || status > 599) {
    status = 500;
  }
  res.status(status).json({ error: "Requête refusée ou incident" });
});
app.listen(3000, "127.0.0.1");

