import { useEffect } from 'react';
function Titree(props) {
  const nom = props.nom;
  useEffect(() => {
    const ancien = document.title;
    document.title = 'Lecture de ' + nom;
    return () => {
      document.title = ancien;
    };
  }, [nom]);
  return <p>Bonjour {nom}</p>;
}

function charger(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id === 'lire') resolve('Lire');
      else reject(new Error('Activité inconnue'));
    }, 300);
  });
}

import { useEffect, useState } from 'react';
export default function Detail({ id }) {
  const [etat, setEtat] = useState({
    status: 'loading', texte: ''
  });
  // Insérer ici le bloc useEffect ci-dessous.
  if (etat.status === 'loading') return <p>Chargement…</p>;
  if (etat.status === 'error') return <p>Erreur : {etat.texte}</p>;
  return <p>{etat.texte}</p>;
}

useEffect(() => {
  let actif = true;
  setEtat({ status: 'loading', texte: '' });
  async function lancer() {
    try {
      const texte = await charger(id);
      if (actif) setEtat({ status: 'success', texte });
    } catch (e) {
      if (actif) setEtat({ status: 'error', texte: e.message });
    }
  }
  lancer();
  return () => { actif = false; };
}, [id]);

import { useParams, Navigate } from 'react-router';
function Page() {
  const params = useParams();
  const id = params.id;
  if (id !== 'lire' && id !== 'marcher') {
    return <Navigate to="/activites/lire" replace />;
  }
  return <p>Activité : {id}</p>;
}

import { BrowserRouter, Routes, Route } from 'react-router';
export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/activites/:id" element={<Page />} />
        <Route path="*"
          element={<Navigate to="/activites/lire" replace />} />
      </Routes>
    </BrowserRouter>
  );
}
